527	        requireDistinct(request.allocations(), ClientPaymentRequest.Allocation::invoiceId);
528	        ClientPayment lump = clientPayments.saveAndFlush(new ClientPayment(clientId, request.amount(), request.date()));
529	        List<PaymentResponse> shares = request.allocations().stream()
530	                .map(a -> apply(findForClient(clientId, a.invoiceId()), a.amount(),
531	                        () -> new Payment(a.invoiceId(), a.amount(), request.date(), lump.getId())))
532	                .toList();
533	        return ClientPaymentResponse.from(lump, shares);
534	    }
535	
536	    /**
537	     * Puts part of a client's held deposits toward several of their owing invoices, today. The
538	     * shares may not add up to more than is still held, each invoice may appear once, and each share
539	     * is recorded as a payment against its own invoice under the same rules as a lump payment's.
540	     */
541	    @Transactional
542	    public DepositApplicationResponse applyDeposits(Long clientId, DepositApplicationRequest request) {
543	        requireClient(clientId);
544	        BigDecimal allocated = total(request.allocations(), DepositApplicationRequest.Allocation::amount);
545	        BigDecimal held = deposits.sumAmountByClientId(clientId)
546	                .subtract(depositApplications.sumAmountByClientId(clientId))
547	                .subtract(refunds.sumFromDepositsByClientId(clientId));
548	        if (allocated.compareTo(held) > 0) {
549	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
550	                    "The shares add up to more than the deposits held");
551	        }
552	        requireDistinct(request.allocations(), DepositApplicationRequest.Allocation::invoiceId);
553	        LocalDate today = LocalDate.now(clock);
554	        DepositApplication application = depositApplications.saveAndFlush(
555	                new DepositApplication(clientId, allocated, today));
556	        List<PaymentResponse> shares = request.allocations().stream()
557	                .map(a -> apply(findForClient(clientId, a.invoiceId()), a.amount(),
558	                        () -> Payment.fromDeposits(a.invoiceId(), a.amount(), today, application.getId())))
559	                .toList();
560	        audit.record("DEPOSIT_APPLIED id=" + application.getId() + " client=" + clientId
561	                + " amount=" + application.getAmount().toPlainString());
562	        return DepositApplicationResponse.from(application, shares);
563	    }
564	
565	    private void requireClient(Long clientId) {
566	        if (!clients.existsById(clientId)) {
567	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client");
568	        }
569	    }
570	
571	    private static <A> BigDecimal total(List<A> allocations, Function<A, BigDecimal> amount) {
572	        return allocations.stream().map(amount).reduce(BigDecimal.ZERO, BigDecimal::add);
573	    }
574	
575	    private static <A> void requireDistinct(List<A> allocations, Function<A, Long> invoiceId) {
576	        Set<Long> seen = new HashSet<>();
577	        for (A a : allocations) {
578	            if (!seen.add(invoiceId.apply(a))) {
579	                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Each invoice may be paid only once");
580	            }
581	        }
582	    }
583	
584	    private PaymentResponse apply(Invoice invoice, BigDecimal amount, Supplier<Payment> payment) {
585	        if (invoice.getStatus() == InvoiceStatus.DRAFT) {
586	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Send the invoice before recording a payment");
587	        }
588	        if (invoice.getStatus() == InvoiceStatus.VOID) {
589	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice has been cancelled");
590	        }
591	        if (invoice.getStatus() == InvoiceStatus.WRITTEN_OFF) {
592	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice has been written off");
593	        }
594	        if (!invoice.getStatus().isOwing()) {
595	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice is already paid");
596	        }
597	        BigDecimal paid = payments.sumAmountByInvoiceId(invoice.getId()).add(amount);
598	        BigDecimal credited = creditNotes.sumAmountByInvoiceId(invoice.getId());
599	        BigDecimal settled = paid.add(credited);
600	        if (settled.compareTo(invoice.getAmount()) > 0) {
601	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Payment is more than the balance due");
602	        }
603	        Payment saved = payments.saveAndFlush(payment.get());
604	        invoice.applySettledTotals(paid, credited);
605	        invoices.flush();
606	        audit.record("PAYMENT_RECORDED id=" + saved.getId() + " amount=" + saved.getAmount().toPlainString());
607	        return PaymentResponse.from(saved);
608	    }
609	
610	    private Invoice findForClient(Long clientId, Long invoiceId) {
611	        return invoices.findById(invoiceId)
612	                .filter(i -> i.getProject().getClient().getId().equals(clientId))
613	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown invoice"));
614	    }
615	
616	    private Invoice find(Long projectId, Long invoiceId) {
